    glyphs: "import Toybox.Lang;\n\n// Stroke font on an 8 x 12 box (y down). Entry: [advance width, x, y, x, y, ...];\n// a 99,99 pair lifts the pen. Turkish marks (dot, cedilla, breve) are added in the view.\nmodule Glyphs {\n    const GAP = 3;\n    const SPACE = 5;\n    const DATA = {\n        '0' => [8, 2,0, 6,0, 8,2, 8,10, 6,12, 2,12, 0,10, 0,2, 2,0],\n        '1' => [8, 1,3, 4,0, 4,12, 99,99, 1,12, 7,12],\n        '2' => [8, 0,2, 2,0, 6,0, 8,2, 8,4, 0,12, 8,12],\n        '3' => [8, 0,0, 6,0, 8,2, 8,4, 6,6, 3,6, 99,99, 6,6, 8,8, 8,10, 6,12, 0,12],\n        '4' => [8, 6,12, 6,0, 0,8, 8,8],\n        '5' => [8, 8,0, 0,0, 0,5, 5,5, 8,7, 8,10, 6,12, 0,12],\n        '6' => [8, 8,0, 2,0, 0,2, 0,10, 2,12, 6,12, 8,10, 8,7, 6,5, 0,5],\n        '7' => [8, 0,0, 8,0, 2,12],\n        '8' => [8, 2,0, 6,0, 8,2, 8,4, 6,6, 2,6, 0,4, 0,2, 2,0, 99,99, 2,6, 6,6, 8,8, 8,10, 6,12, 2,12, 0,10, 0,8, 2,6],\n        '9' => [8, 0,12, 6,12, 8,10, 8,2, 6,0, 2,0, 0,2, 0,5, 2,7, 8,7],\n        ':' => [2, 1,3, 1,3, 99,99, 1,9, 1,9],\n        '.' => [2, 1,11, 1,11],\n        '-' => [6, 0,6, 6,6],\n        '°' => [5, 0,0, 4,0, 4,4, 0,4, 0,0],\n        'A' => [8, 0,12, 0,3, 3,0, 5,0, 8,3, 8,12, 99,99, 0,7, 8,7],\n        'B' => [8, 0,0, 0,12, 6,12, 8,10, 8,8, 6,6, 0,6, 99,99, 0,0, 6,0, 8,2, 8,4, 6,6],\n        'C' => [8, 8,2, 6,0, 2,0, 0,2, 0,10, 2,12, 6,12, 8,10],\n        'D' => [8, 0,0, 0,12, 5,12, 8,9, 8,3, 5,0, 0,0],\n        'E' => [8, 8,0, 0,0, 0,12, 8,12, 99,99, 0,6, 6,6],\n        'G' => [8, 8,2, 6,0, 2,0, 0,2, 0,10, 2,12, 6,12, 8,10, 8,7, 4,7],\n        'H' => [8, 0,0, 0,12, 99,99, 8,0, 8,12, 99,99, 0,6, 8,6],\n        'I' => [6, 0,0, 6,0, 99,99, 3,0, 3,12, 99,99, 0,12, 6,12],\n        'K' => [8, 0,0, 0,12, 99,99, 8,0, 0,7, 99,99, 3,6, 8,12],\n        'L' => [8, 0,0, 0,12, 8,12],\n        'M' => [8, 0,12, 0,0, 4,6, 8,0, 8,12],\n        'N' => [8, 0,12, 0,0, 8,12, 8,0],\n        'O' => [8, 2,0, 6,0, 8,2, 8,10, 6,12, 2,12, 0,10, 0,2, 2,0],\n        'P' => [8, 0,12, 0,0, 6,0, 8,2, 8,5, 6,7, 0,7],\n        'R' => [8, 0,12, 0,0, 6,0, 8,2, 8,5, 6,7, 0,7, 99,99, 4,7, 8,12],\n        'S' => [8, 8,2, 6,0, 2,0, 0,2, 0,4, 2,6, 6,6, 8,8, 8,10, 6,12, 2,12, 0,10],\n        'T' => [8, 0,0, 8,0, 99,99, 4,0, 4,12],\n        'U' => [8, 0,0, 0,10, 2,12, 6,12, 8,10, 8,0],\n        'Y' => [8, 0,0, 4,6, 8,0, 99,99, 4,6, 4,12],\n        'Z' => [8, 0,0, 8,0, 0,12, 8,12]\n    };\n    const MARK_DOT     = [3,-3, 3,-3];\n    const MARK_CEDILLA = [4,12, 4,14, 2,15];\n    const MARK_BREVE   = [2,-4, 4,-2, 6,-4];\n}\n",
    mapdata: "import Toybox.Lang;\n\n// 5-degree dot-matrix land mask, 72 columns (lon -180..180) x 27 rows (lat 75N..60S).\n// Each row is 3 words of 24 bits; bit i of word k is column 24*k+i. Generated, do not edit.\nmodule MapData {\n    const COLS = 72;\n    const ROWS = 27;\n    const BITS = [\n        0x1FC000, 0x8000FE, 0x003FF0,\n        0x61FFFB, 0xFF803E, 0xFFFFFF,\n        0x01FFF8, 0xFFE00C, 0x7FFFFF,\n        0xF3FE10, 0xFF4800, 0x18FFFF,\n        0xFFFC00, 0xFFEC01, 0x00FFFF,\n        0x7FF800, 0xFFF801, 0x00FFFF,\n        0x3FF800, 0xB3DC00, 0x017FFF,\n        0x1FF800, 0xFC0C00, 0x00AFFF,\n        0x0FF000, 0xF87C00, 0x000FFF,\n        0x01E000, 0xFFFE00, 0x000FFF,\n        0x018000, 0xF7FE00, 0x0007FC,\n        0x078000, 0x7FFE00, 0x000398,\n        0x040000, 0x3FFE00, 0x000308,\n        0xF00000, 0x3FFC01, 0x000000,\n        0xF00000, 0x1FC003, 0x000C80,\n        0xF00000, 0x0FC00F, 0x001500,\n        0xF00000, 0x0FC01F, 0x010000,\n        0xE00000, 0x0F801F, 0x004000,\n        0xC00000, 0x2FC00F, 0x01F000,\n        0xC00000, 0x27800F, 0x03F800,\n        0xC00000, 0x078003, 0x07F800,\n        0xC00000, 0x030003, 0x07F800,\n        0xE00000, 0x000000, 0x030000,\n        0x600000, 0x000000, 0x000000,\n        0x600000, 0x000000, 0x000000,\n        0x600000, 0x000000, 0x000000,\n        0x000000, 0x000000, 0x000000,\n    ];\n}\n",
